-- Schema only: no user recipe values or credentials.
CREATE TABLE `collections` (`id` TEXT NOT NULL, `nameFr` TEXT NOT NULL, `nameEn` TEXT NOT NULL, `descriptionFr` TEXT, `descriptionEn` TEXT, `recipeIdsJson` TEXT NOT NULL, `sortOrder` TEXT, PRIMARY KEY(`id`));
CREATE TABLE `contextual_substitution_rules` (`id` TEXT NOT NULL, `fromIngredientRefId` TEXT NOT NULL, `toIngredientRefId` TEXT NOT NULL, `conversionType` TEXT NOT NULL, `ratio` REAL, `offset` REAL, `allowedDishTypesJson` TEXT NOT NULL, `excludedDishTypesJson` TEXT NOT NULL, `allowedIngredientRolesJson` TEXT NOT NULL, `excludedIngredientRolesJson` TEXT NOT NULL, `allowedCookingMethodsJson` TEXT NOT NULL, `confidence` TEXT NOT NULL, `riskLevel` TEXT NOT NULL, `notesFr` TEXT, `notesEn` TEXT, `warningTextFr` TEXT, `warningTextEn` TEXT, `updatedAt` TEXT NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE `ingredient_references` (`id` TEXT NOT NULL, `nameFr` TEXT NOT NULL, `nameEn` TEXT NOT NULL, `category` TEXT NOT NULL, `aliasesFrJson` TEXT NOT NULL, `aliasesEnJson` TEXT NOT NULL, `defaultDensity` REAL, `unitMappingsJson` TEXT NOT NULL, `updatedAt` TEXT NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE `library_metadata` (`libraryId` TEXT NOT NULL, `createdAt` TEXT NOT NULL, `updatedAt` TEXT NOT NULL, `exportedAt` TEXT NOT NULL, `appVersion` TEXT, `deviceId` TEXT, PRIMARY KEY(`libraryId`));
CREATE TABLE `library_settings` (`id` TEXT NOT NULL, `language` TEXT NOT NULL, `driveSyncEnabled` INTEGER NOT NULL, `driveFileName` TEXT, `driveFolderId` TEXT, `openSourceInAppBrowser` INTEGER, PRIMARY KEY(`id`));
CREATE TABLE `recipe_collection_cross_refs` (`recipeId` TEXT NOT NULL, `collectionId` TEXT NOT NULL, `position` INTEGER NOT NULL, PRIMARY KEY(`recipeId`, `collectionId`), FOREIGN KEY(`recipeId`) REFERENCES `recipes`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE `recipe_ingredient_line_substitutions` (`id` TEXT NOT NULL, `ingredientLineId` TEXT NOT NULL, `position` INTEGER NOT NULL, `substitutionRuleId` TEXT, `contextualSubstitutionRuleId` TEXT, `isPreferred` INTEGER NOT NULL, `customLabelFr` TEXT, `customLabelEn` TEXT, `createdAt` TEXT NOT NULL, `updatedAt` TEXT NOT NULL, PRIMARY KEY(`id`), FOREIGN KEY(`ingredientLineId`) REFERENCES `recipe_ingredient_lines`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE `recipe_ingredient_lines` (`id` TEXT NOT NULL, `recipeId` TEXT NOT NULL, `position` INTEGER NOT NULL, `ingredientRefId` TEXT, `originalText` TEXT NOT NULL, `quantity` REAL, `unit` TEXT, `ingredientName` TEXT NOT NULL, `preparation` TEXT, `optional` INTEGER NOT NULL, `notes` TEXT, `groupName` TEXT, PRIMARY KEY(`id`), FOREIGN KEY(`recipeId`) REFERENCES `recipes`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE `recipe_links` (`id` TEXT NOT NULL, `recipeId` TEXT NOT NULL, `targetRecipeId` TEXT NOT NULL, `linkType` TEXT NOT NULL, `labelFr` TEXT, `labelEn` TEXT, `position` INTEGER NOT NULL, PRIMARY KEY(`id`), FOREIGN KEY(`recipeId`) REFERENCES `recipes`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE `recipe_tag_cross_refs` (`recipeId` TEXT NOT NULL, `tagId` TEXT NOT NULL, `position` INTEGER NOT NULL, PRIMARY KEY(`recipeId`, `tagId`), FOREIGN KEY(`recipeId`) REFERENCES `recipes`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE `recipes` (`id` TEXT NOT NULL, `createdAt` TEXT NOT NULL, `updatedAt` TEXT NOT NULL, `titleFr` TEXT NOT NULL, `titleEn` TEXT NOT NULL, `descriptionFr` TEXT NOT NULL, `descriptionEn` TEXT NOT NULL, `instructionsFr` TEXT NOT NULL, `instructionsEn` TEXT NOT NULL, `notesFr` TEXT NOT NULL, `notesEn` TEXT NOT NULL, `sourceUrl` TEXT, `sourceName` TEXT, `servingsAmount` REAL, `servingsUnit` TEXT, `prepTimeMinutes` INTEGER, `cookTimeMinutes` INTEGER, `totalTimeMinutes` INTEGER, `userRating` REAL, `madeCount` INTEGER, `lastMadeAt` TEXT, `mainPhotoId` TEXT, `deletedAt` TEXT, `photosJson` TEXT NOT NULL, `attachmentsJson` TEXT NOT NULL, `importMetadataJson` TEXT, PRIMARY KEY(`id`));
CREATE TABLE `tags` (`id` TEXT NOT NULL, `nameFr` TEXT NOT NULL, `nameEn` TEXT NOT NULL, `slug` TEXT NOT NULL, `category` TEXT NOT NULL, PRIMARY KEY(`id`));
CREATE INDEX `index_contextual_substitution_rules_fromIngredientRefId` ON `contextual_substitution_rules` (`fromIngredientRefId`);
CREATE INDEX `index_contextual_substitution_rules_toIngredientRefId` ON `contextual_substitution_rules` (`toIngredientRefId`);
CREATE INDEX `index_recipe_collection_cross_refs_collectionId` ON `recipe_collection_cross_refs` (`collectionId`);
CREATE UNIQUE INDEX `index_recipe_collection_cross_refs_recipeId_position` ON `recipe_collection_cross_refs` (`recipeId`, `position`);
CREATE INDEX `index_recipe_ingredient_line_substitutions_ingredientLineId` ON `recipe_ingredient_line_substitutions` (`ingredientLineId`);
CREATE UNIQUE INDEX `index_recipe_ingredient_line_substitutions_ingredientLineId_position` ON `recipe_ingredient_line_substitutions` (`ingredientLineId`, `position`);
CREATE INDEX `index_recipe_ingredient_lines_ingredientRefId` ON `recipe_ingredient_lines` (`ingredientRefId`);
CREATE INDEX `index_recipe_ingredient_lines_recipeId` ON `recipe_ingredient_lines` (`recipeId`);
CREATE UNIQUE INDEX `index_recipe_ingredient_lines_recipeId_position` ON `recipe_ingredient_lines` (`recipeId`, `position`);
CREATE INDEX `index_recipe_links_recipeId` ON `recipe_links` (`recipeId`);
CREATE UNIQUE INDEX `index_recipe_links_recipeId_position` ON `recipe_links` (`recipeId`, `position`);
CREATE INDEX `index_recipe_links_targetRecipeId` ON `recipe_links` (`targetRecipeId`);
CREATE UNIQUE INDEX `index_recipe_tag_cross_refs_recipeId_position` ON `recipe_tag_cross_refs` (`recipeId`, `position`);
CREATE INDEX `index_recipe_tag_cross_refs_tagId` ON `recipe_tag_cross_refs` (`tagId`);
